#define _GNU_SOURCE
#include <dlfcn.h>
#include <unistd.h>
#include <stdio.h>
#include <string.h>
static ssize_t (*real_write)(int,const void*,size_t);
static int nw=0;
ssize_t write(int fd, const void*buf, size_t n){
  if(!real_write) real_write=dlsym(RTLD_NEXT,"write");
  if(fd==1){ nw++; char m[128]; int l=snprintf(m,sizeof m,"[SHIM write#%d fd=1 len=%zu]\n",nw,n); real_write(2,m,l);} 
  return real_write(fd,buf,n);
}
EOF
