cd /tmp && cat > /tmp/s2.c <<'EOF'
#define _GNU_SOURCE
#include <dlfcn.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
static void note(const char*s,size_t n){ char m[256]; int l=snprintf(m,sizeof m,"[%s len=%zu]\n",s,n); (void)!write(2,m,l);} 
size_t fwrite(const void*p,size_t sz,size_t nm,FILE*f){ static size_t(*r)(const void*,size_t,size_t,FILE*); if(!r)r=dlsym(RTLD_NEXT,"fwrite"); if(f==stdout) note("fwrite",sz*nm); return r(p,sz,nm,f);} 
size_t fwrite_unlocked(const void*p,size_t sz,size_t nm,FILE*f){ static size_t(*r)(const void*,size_t,size_t,FILE*); if(!r)r=dlsym(RTLD_NEXT,"fwrite_unlocked"); if(f==stdout) note("fwrite_unlocked",sz*nm); return r(p,sz,nm,f);} 
int fputc(int c,FILE*f){ static int(*r)(int,FILE*); if(!r)r=dlsym(RTLD_NEXT,"fputc"); if(f==stdout) note("fputc",1); return r(c,f);} 
int fflush(FILE*f){ static int(*r)(FILE*); if(!r)r=dlsym(RTLD_NEXT,"fflush"); if(f==stdout) note("fflush",0); return r(f);} 
EOF
